// Batch Actions of the purchase service through the platform Action kernel.
package candidate

import (
	"context"
	"errors"
	"net/http"

	"github.com/XUJiahua/enterprise_agent/internal/action"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// adapt converts kernel rejections at the service boundary.
func adapt(err error) error {
	var denied *action.Rejection
	if errors.As(err, &denied) {
		return &protocol.Rejection{Status: denied.Status}
	}
	return err
}

func batch(executor *action.Executor, op action.Operation) protocol.Handler {
	return func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		done, replayed, err := executor.Run(ctx, u, op, key, action.Request{IDs: ids})
		if err != nil {
			return protocol.Result{}, false, adapt(err)
		}
		return protocol.Result{Field: op.Field, IDs: done}, replayed, nil
	}
}

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	executor, err := action.New(ctx, pool)
	if err != nil {
		return nil, err
	}
	reopen := func(ctx context.Context, u app.Identity, key, id, reason string) (protocol.ItemResult, bool, error) {
		done, replayed, err := executor.Run(ctx, u, reopenOp, key, action.Request{IDs: []string{id}, Reason: reason})
		if err != nil {
			return protocol.ItemResult{}, false, adapt(err)
		}
		return protocol.ItemResult{ID: done[0], Status: reopenOp.To}, replayed, nil
	}
	countersign := func(ctx context.Context, u app.Identity, key, id string, amount int) (protocol.ItemResult, bool, error) {
		done, replayed, err := executor.Run(ctx, u, countersignOp, key, action.Request{IDs: []string{id}, Amount: amount})
		if err != nil {
			return protocol.ItemResult{}, false, adapt(err)
		}
		if replayed {
			// The kernel's request fingerprint covers only the target ID, so a replay
			// must still confirm the same amount as the first request did.
			if err = sameAmount(ctx, pool, u, done[0], amount); err != nil {
				return protocol.ItemResult{}, false, err
			}
		}
		return protocol.ItemResult{ID: done[0], Status: countersignOp.To}, replayed, nil
	}
	routes := protocol.HTTP(protocol.Routes{"/purchases/bulk-approve": batch(executor, approveOp), "/purchases/bulk-reject": batch(executor, rejectOp)}, fallback)
	return protocol.Confirm("countersign", "approver", countersign, protocol.Item("reopen", "requester", reopen, routes)), nil
}

// sameAmount rejects a replay whose confirmed amount differs from the purchase
// amount. Purchase amounts are immutable for the runtime role, so the stored
// request was confirmed against the same value.
func sameAmount(ctx context.Context, pool *pgxpool.Pool, u app.Identity, id string, amount int) error {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
		return err
	}
	var current int
	err = tx.QueryRow(ctx, `SELECT amount FROM "Purchase" WHERE id=$1 AND "tenantId"=$2`, id, u.Tenant).Scan(&current)
	if errors.Is(err, pgx.ErrNoRows) {
		return &protocol.Rejection{Status: 409}
	}
	if err != nil {
		return err
	}
	if current != amount {
		return &protocol.Rejection{Status: 409}
	}
	return tx.Commit(ctx)
}
